using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using MYOB.Data;using MYOB.Models;using MYOB.Services;using MYOB.Support;
namespace MYOB.Pages.Operations.SupplierPayments;public class IndexModel(ApplicationDbContext db,IPermissionService permissions):PageModel
{
 public IReadOnlyList<SupplierPayment> Items{get;private set;}=[];[BindProperty(SupportsGet=true)]public string? Search{get;set;}[BindProperty(SupportsGet=true)]public int PageNumber{get;set;}=1;public int TotalPages{get;private set;}public bool CanAdd{get;private set;}public bool CanUpdate{get;private set;}public bool CanDelete{get;private set;}
 public async Task OnGetAsync(){const int size=15;var q=db.SupplierPayments.Include(x=>x.Supplier).Include(x=>x.SupplierReceipt).Include(x=>x.PaymentMethod).AsNoTracking();if(!string.IsNullOrWhiteSpace(Search))q=q.Where(x=>x.Supplier.Name.Contains(Search)||x.SupplierReceipt.PolicyNumber.Contains(Search)||x.PaymentMethod.Name.Contains(Search));var count=await q.CountAsync();TotalPages=Math.Max(1,(int)Math.Ceiling(count/(double)size));PageNumber=Math.Clamp(PageNumber,1,TotalPages);Items=await q.OrderByDescending(x=>x.Date).ThenByDescending(x=>x.CreatedAt).Skip((PageNumber-1)*size).Take(size).ToListAsync();CanAdd=await permissions.HasAsync(User,ScreenCatalog.SupplierPayments,PermissionAction.Add);CanUpdate=await permissions.HasAsync(User,ScreenCatalog.SupplierPayments,PermissionAction.Update);CanDelete=await permissions.HasAsync(User,ScreenCatalog.SupplierPayments,PermissionAction.Delete);}
 public async Task<IActionResult> OnPostDeleteAsync(Guid id){if(!await permissions.HasAsync(User,ScreenCatalog.SupplierPayments,PermissionAction.Delete))return Forbid();var x=await db.SupplierPayments.SingleOrDefaultAsync(x=>x.Id==id);if(x is null)return NotFound();x.IsDeleted=true;x.DeletedAt=DateTimeOffset.UtcNow;x.DeletedBy=User.Identity?.Name;await db.SaveChangesAsync();return RedirectToPage();}
}
